# Try direct environment path
import os, re

d = os.environ.get('RLM_SESSION_DIR', '')
print(f"RLM_SESSION_DIR: {d}")

# List files in potential locations
for loc in [d, d + '/../../sessions', d.replace('runs', 'sessions')]:
    if os.path.exists(loc):
        print(f"Exists: {loc}, type: {type(os.stat(loc))}")
        if os.path.isdir(loc):
            for f in os.listdir(loc)[:10]:
                print(f"  {f}")
